insert into categories (slug,name,nav_label,tagline,description,accent,sort_order) values ('ai-micro-tools','AI Micro Tools','AI Tools','Single-purpose tools that do one job well.','Focused utilities for writing, documents and data extraction. Run them in the browser, pay once, and use the included monthly credits or your own API key.','#7C3AED',0) on conflict (slug) do update set name=excluded.name, tagline=excluded.tagline, description=excluded.description;
