insert into categories (slug,name,nav_label,tagline,description,accent,sort_order) values ('ai-agents','AI Agents','AI Agents','Configurable agents that work from your data.','Agents with tools, memory and guardrails. Run them hosted on AgentForge or self-host them, configure them in Agent Studio, and keep a full log of every step.','#6366F1',2) on conflict (slug) do update set name=excluded.name, tagline=excluded.tagline, description=excluded.description;
