insert into products (id,slug,category_slug,subcategory,title,short_description,description,price_amount,currency,status,functional,delivery,hosting,difficulty,license,version,cost_per_run_low,cost_per_run_high,cost_note,benefits,use_cases,audience,industries,inputs,outputs,requirements,installation,providers,demo_available,seo_title,seo_description,seo_keywords,published_at) values ('prd_001','ai-resume-cover-letter-builder','ai-micro-tools','Career','AI Resume & Cover Letter Builder','Turn your experience and a target job posting into a tailored resume and cover letter.','Paste your work history and the job description you are applying for. The builder maps your experience to the requirements the posting states, rewrites bullet points around outcomes, and drafts a matching cover letter. It never invents employers, dates or qualifications: anything it cannot ground in your input is listed as a gap for you to fill in.',1000,'EUR','published',true,'hosted-tool','hosted','beginner','personal','1.0.0',0.002,0.02,'Estimated provider cost of €0.002–€0.02 per run, depending on model and input size. Hosted runs use included credits; with your own API key the provider bills you directly. Estimates, not guarantees.',array['Maps your experience to each stated job requirement','Built for: tailoring an application to one specific role','Transparent per-run cost estimates before you run','Nothing to install']::text[],array['Tailoring an application to one specific role','Refreshing an outdated CV','Reframing experience when changing careers']::text[],array['Job seekers','Career coaches','Graduates']::text[],array['Any']::text[],array['Work history (text)','Target job description (text)','Tone']::text[],array['Resume (Markdown)','Cover letter (Markdown)','Requirement gap checklist']::text[],array['A modern browser','An AgentForge account']::text[],array['Purchase the tool; access is granted after the payment provider confirms the payment.','Open Dashboard → My AI tools and launch the tool.','Optional: add your own provider API key under Dashboard → Integrations to run on your account instead of included credits.']::text[],array['OpenAI','Anthropic','Google Gemini']::text[],true,'AI Resume & Cover Letter Builder — €10 | AgentForge AI','Turn your experience and a target job posting into a tailored resume and cover letter.',array['ai resume & cover letter builder','career','maps your experience to each stated job requirement','ats-friendly resume in clean markdown']::text[],'2026-11-18') on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
