ed credits.']::text[],array['OpenAI','Anthropic','Google Gemini']::text[],true,'AI PDF Summarizer — €19 | AgentForge AI','Upload a PDF and get an executive summary and key points with page references.',array['ai pdf summarizer','documents','page-aware text extraction','brief, standard or detailed summaries']::text[],'2026-11-19') on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
