i']::text[],false,'AI Meeting Notes Generator — €25 | AgentForge AI','Turn meeting transcripts into decisions, owned action items and a follow-up email.',array['ai meeting notes generator','productivity','decision extraction with transcript quotes','action items with owner and due date']::text[],null) on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
