 | AgentForge AI','An n8n workflow that classifies incoming Gmail, applies labels and drafts replies for review.',array['gmail inbox organizer','email','custom classification categories','automatic gmail labelling']::text[],null) on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
