ok.']::text[],array['OpenAI','Anthropic','Google Gemini']::text[],true,'AI Knowledge Base Agent — €129 | AgentForge AI','Ask questions over your own documents and get answers that cite the exact passages.',array['ai knowledge base agent','knowledge','private knowledge bases per workspace','lexical retrieval, plus embeddings when configured']::text[],'2026-11-23') on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
