Forge AI','Summarises applications against your stated criteria for a human recruiter. It makes no hiring decisions.',array['ai recruitment assistant','hr','criteria-based evidence summaries','no autonomous ranking or rejection']::text[],null) on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
