insert into products (id,slug,category_slug,subcategory,title,short_description,description,price_amount,currency,status,functional,delivery,hosting,difficulty,license,version,cost_per_run_low,cost_per_run_high,cost_note,benefits,use_cases,audience,industries,inputs,outputs,requirements,installation,providers,demo_available,seo_title,seo_description,seo_keywords,published_at) values ('prd_031','multi-agent-research-team','multi-agent-systems','Research','Multi-Agent Research Team','A planner, researchers, a critic and a writer turn your question and sources into a cited report.','You provide a research question and the sources to work from: pasted text, uploaded documents or public URLs you approve. A planner splits the question into sub-questions, researcher agents extract evidence from the sources, a critic checks each claim against that evidence and flags gaps, and a writer assembles a structured report in which every claim cites a source. Each step is logged with its inputs, outputs and token usage.',24900,'EUR','published',true,'cloud-agent','hosted','intermediate','commercial','1.0.0',0.02,0.4,'Estimated provider cost of €0.020–€0.40 per run, depending on model and input size. Hosted runs use included credits; with your own API key the provider bills you directly. Estimates, not guarantees.',array['Planner, researcher, critic and writer roles','Built for: market and policy briefs','Transparent per-run cost estimates before you run','Nothing to install']::text[],array['Market and policy briefs','Literature reviews','Due-diligence preparation']::text[],array['Analysts','Consultants','Founders']::text[],array['Consulting','Research','Finance']::text[],array['Research question','Sources (text, files, approved URLs)','Report depth']::text[],array['Cited report','Evidence table','Gap list','Execution log']::text[],array['An AgentForge account','Optional: your own OpenAI, Anthropic or Gemini API key']::text[],array['Purchase the agent; it appears under Dashboard → My agents.','Open it in Agent Studio, review the default instructions, model and tools.','Add knowledge or sources, then run it manually or from a webhook.']::text[],array['OpenAI','Anthropic','Google Gemini']::text[],true,'Multi-Agent Research Team — €249 | AgentForge AI','A planner, researchers, a critic and a writer turn your question and sources into a cited report.',array['multi-agent research team','research','planner, researcher, critic and writer roles','every claim cites a provided source']::text[],'2026-11-24') on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
