 agents that work in a sandboxed repo and open pull requests.',array['ai software development team','engineering','sandboxed repository execution','test-driven iterations']::text[],null) on conflict (id) do update set title=excluded.title, short_description=excluded.short_description, description=excluded.description, updated_at=now();
